DROP DATABASE IF EXISTS hospital_management;
CREATE DATABASE hospital_management;
USE hospital_management;

CREATE TABLE users (user_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(100) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL,phone VARCHAR(15),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE patients (patient_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,date_of_birth DATE,gender VARCHAR(10),blood_group VARCHAR(5),address VARCHAR(255),emergency_contact VARCHAR(15),FOREIGN KEY (user_id) REFERENCES users(user_id));
CREATE TABLE specializations (specialization_id INT AUTO_INCREMENT PRIMARY KEY,specialization_name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE doctors (doctor_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,specialization_id INT NOT NULL,qualification VARCHAR(100),experience_years INT,availability_status VARCHAR(20) DEFAULT 'Available',FOREIGN KEY (user_id) REFERENCES users(user_id),FOREIGN KEY (specialization_id) REFERENCES specializations(specialization_id));
CREATE TABLE medical_records (record_id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,diagnosis VARCHAR(255),symptoms VARCHAR(500),treatment VARCHAR(500),doctor_notes TEXT,record_date DATE,FOREIGN KEY (patient_id) REFERENCES patients(patient_id));
CREATE TABLE medicines (medicine_id INT AUTO_INCREMENT PRIMARY KEY,medicine_name VARCHAR(100) NOT NULL,category VARCHAR(100),manufacturer VARCHAR(100),price DECIMAL(10,2),quantity INT DEFAULT 0,expiry_date DATE);
CREATE TABLE prescriptions (prescription_id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,doctor_id INT NOT NULL,medicine_id INT NOT NULL,dosage VARCHAR(100),duration VARCHAR(100),prescription_date DATE,FOREIGN KEY (patient_id) REFERENCES patients(patient_id),FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id),FOREIGN KEY (medicine_id) REFERENCES medicines(medicine_id));
CREATE TABLE lab_tests (test_id INT AUTO_INCREMENT PRIMARY KEY,test_name VARCHAR(100) NOT NULL,test_description VARCHAR(255),test_cost DECIMAL(10,2));
CREATE TABLE lab_reports (report_id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,test_id INT NOT NULL,doctor_id INT NOT NULL,result VARCHAR(500),report_date DATE,remarks VARCHAR(255),FOREIGN KEY (patient_id) REFERENCES patients(patient_id),FOREIGN KEY (test_id) REFERENCES lab_tests(test_id),FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id));
CREATE TABLE bills (bill_id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,bill_date DATE,total_amount DECIMAL(10,2) NOT NULL,payment_status VARCHAR(20) DEFAULT 'Pending',FOREIGN KEY (patient_id) REFERENCES patients(patient_id));
CREATE TABLE payments (payment_id INT AUTO_INCREMENT PRIMARY KEY,bill_id INT NOT NULL,amount_paid DECIMAL(10,2) NOT NULL,payment_method VARCHAR(50),payment_date DATE,FOREIGN KEY (bill_id) REFERENCES bills(bill_id));
CREATE TABLE insurance (insurance_id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,insurance_provider VARCHAR(100),policy_number VARCHAR(100) UNIQUE,coverage_amount DECIMAL(10,2),claim_status VARCHAR(30) DEFAULT 'Pending',FOREIGN KEY (patient_id) REFERENCES patients(patient_id));













SELECT 'users' AS table_name,COUNT(*) AS records FROM users
UNION ALL SELECT 'patients',COUNT(*) FROM patients

UNION ALL SELECT 'doctors',COUNT(*) FROM doctors
UNION ALL SELECT 'medical_records',COUNT(*) FROM medical_records
UNION ALL SELECT 'medicines',COUNT(*) FROM medicines
UNION ALL SELECT 'prescriptions',COUNT(*) FROM prescriptions
UNION ALL SELECT 'lab_tests',COUNT(*) FROM lab_tests
UNION ALL SELECT 'lab_reports',COUNT(*) FROM lab_reports
UNION ALL SELECT 'bills',COUNT(*) FROM bills
UNION ALL SELECT 'payments',COUNT(*) FROM payments
UNION ALL SELECT 'insurance',COUNT(*) FROM insurance;
USE hospital_management;

SHOW TABLES;
SHOW DATABASES;
SELECT * FROM doctors;
DESCRIBE doctors;
